package com.drivique.api.model;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="user_saved_payment_methods",schema="billing")
public class UserSavedPaymentMethod { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="gateway_provider",nullable=false,length=30) private String gatewayProvider="WOMPI"; @Column(name="payment_token",nullable=false,unique=true,length=255) private String paymentToken; @Column(name="card_brand",nullable=false,length=50) private String cardBrand; @JdbcTypeCode(SqlTypes.CHAR) @Column(name="last_four",nullable=false,length=4,columnDefinition="char(4)") private String lastFour; @Column(name="exp_month",nullable=false) private short expMonth; @Column(name="exp_year",nullable=false) private short expYear; @Column(name="is_active",nullable=false) private boolean active=true; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); protected UserSavedPaymentMethod(){} public UserSavedPaymentMethod(User user,String token,String brand,String lastFour,short month,short year){this.user=user;this.paymentToken=token;this.cardBrand=brand;this.lastFour=lastFour;this.expMonth=month;this.expYear=year;} public UUID getId(){return id;} public String getCardBrand(){return cardBrand;} public String getLastFour(){return lastFour;} public short getExpMonth(){return expMonth;} public short getExpYear(){return expYear;} }

